<?php namespace App\Models; use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model; class FoodItem extends Model { use HasFactory; protected $fillable = ['stall_id', 'category_id', 'name', 'description', 'price', 'availability']; protected$casts = ['availability' => 'boolean', 'price' => 'decimal:2']; public function stall() { return $this->belongsTo(Stall::class); } public function category() { return$this->belongsTo(Category::class); } public function orderItems() { return $this->hasMany(OrderItem::class); } public function orders() { return$this->belongsToMany(Order::class, 'order_items')->withPivot('quantity', 'unit_price')->withTimestamps(); } }